import java.util.*;

public class Main {
    int hammingWeight(int n) {
        int count = 0;
        for (int i = 0; i < 32; i++) {                              // always checks all 32 positions
            if (((n >>> i) & 1) == 1) count++;
        }
        return count;
    }

    public static void main(String[] args) {
        int n = 11;
        Main solution = new Main();
        System.out.println(solution.hammingWeight(n));
    }
}

